        'or the journal\'s editorial office — see table below': 'またはジャーナルの編集局 — 以下の表を参照',
        'journal directory': 'ジャーナルディレクトリ',
        'author guide': '著者ガイド',
        'publication ethics policy': '出版倫理ポリシー',
        'with a clear description of the matter.': '問題の明確な説明とともに。',
        'and include the relevant journal name and DOI where applicable.': '該当する場合は、関連するジャーナル名と DOI を含めます。',
        'allows you to filter by subject cluster and keyword. Each journal entry links directly to the journal home page and submission portal. ISSN status is indicated for journals where registration is complete.': '主題クラスタとキーワードでフィルタリングできます。各ジャーナルエントリは、ジャーナルのホームページと投稿ポータルに直接リンクしています。登録が完了したジャーナルにはISSNステータスが表示されます。',
        'A statement identifying each author\'s contribution, where required.': '必要に応じて、各著者の貢献を特定する声明。',
        'A disclosure statement covering financial, personal, or professional interests relevant to the submission.': '提出物に関連する経済的、個人的、または職業上の利益を対象とした開示声明。',
        'Confirmation of relevant ethical approvals for studies involving human participants, patient data, or animal subjects.': '人間の参加者、患者データ、または動物被験者が関与する研究に関連する倫理的承認の確認。',
        'A statement describing data availability underlying the research, where applicable.': '該当する場合、研究の基礎となるデータの利用可能性を説明する声明。',
        'Identification of funding sources and grant numbers, where applicable.': '該当する場合、資金源と補助金番号の特定。',
        'journals.panorama-sg.com': 'journals.panorama-sg.com',
        '. There is no centralised submission system for the entire portfolio.': '。ポートフォリオ全体を集中的に提出するシステムはありません。',
        'or directly at journals.panorama-sg.com/index.php/[journal-id].': 'または journals.panorama-sg.com/index.php/[journal-id] で直接。',
        'to preserve the integrity of the version of record.': 'レコードのバージョンの整合性を維持するため。',
        'Platform administrative and policy contact.': 'プラットフォームの管理およびポリシーに関する連絡先。',
        'Panorama Scholarly Group institutional profile.': 'Panorama Scholarly Group の組織プロフィール。',
        'Guide sections': 'ガイドセクション',
        'CLOCKSS Archived': 'CLOCKSS アーカイブされました',
        'CLOCKSS Archive': 'CLOCKSS アーカイブ',
        'PKP Preservation': 'PKP の保存',
        'ISSN Registered': 'ISSN 登録済み',
        'Editorial responsibilities, peer review conduct, and correction procedures.': '編集上の責任、査読の実施、および修正手順。',
        'Licensing terms, author rights, and repository guidance.': 'ライセンス条項、作成者の権利、およびリポジトリのガイダンス。',
        'Room 1508, 15/F., Office Tower Two, Grand Plaza, 625 Nathan Road, Kowloon, Hong Kong.': '1508号室、15/F.、オフィスタワー2、グランドプラザ、625ネイザンロード、九龍、香港。',
        'Room 1508, 15/F., Office Tower Two': '第2オフィスタワー15階1508号室',
        'Grand Plaza, 625 Nathan Road': 'グランドプラザ、ネイザンロード625',
        'Kowloon, Hong Kong': '香港、九龍',
        'Panorama Scholarly Group Ltd.': 'Panorama Scholarly Group Ltd.',
        'Submissions are handled at journal level. Access the relevant journal\'s submission portal via the': '投稿はジャーナルレベルで処理されます。関連するジャーナルの投稿ポータルにアクセスします。',
        'covers journal selection, submission, peer review, and post-publication rights.': 'ジャーナルの選択、投稿、査読、出版後の権利をカバーします。',
        'Enquiries regarding publication ethics policy, editorial conduct, or appeals processes should be directed to': '出版倫理ポリシー、編集行為、または異議申し立てのプロセスに関するお問い合わせは、次の宛先までお送りください。',
        'Questions about licensing, author rights, or repository terms should reference the': 'ライセンス、作成者の権利、またはリポジトリの条件に関する質問については、',
        'Panorama Scholarly Group\'s journals invite scholars worldwide to join their editorial boards. We welcome researchers with strong academic backgrounds and peer-review experience to help uphold the quality of international scholarly publishing.': 'Panorama Scholarly Group のジャーナルは、世界中の学者を編集委員会に招待しています。私たちは、国際的な学術出版の質を維持するために、強力な学術的背景と査読の経験を持つ研究者を歓迎します。',
        'Please state in your email the journal(s) you wish to join. If unsure, browse the': '参加を希望するジャーナルを電子メールに明記してください。不明な場合は、',
        'to find the best match for your research.': 'あなたの研究に最適なものを見つけてください。',
        'Submission guidance from manuscript preparation to publication.': '原稿作成から掲載までの投稿指導。',
        'This guide covers the full submission process for Panorama Scholarly Group journals — journal selection, ethics requirements, peer review, and post-publication rights.': 'このガイドでは、Panorama Scholarly Group ジャーナルの投稿プロセス全体 (ジャーナルの選択、倫理要件、査読、出版後の権利) について説明します。',
        'Panorama Scholarly Group journals publish on an open access basis. Authors should confirm the applicable licensing terms, APC status, and rights framework before final submission. This information is available on each journal\'s home page and in the': 'Panorama Scholarly Group のジャーナルはオープンアクセスベースで発行されます。著者は、最終提出前に、該当するライセンス条項、APC ステータス、および権利の枠組みを確認する必要があります。この情報は、各ジャーナルのホームページおよび',
        'Submissions are handled at journal level through the journal\'s editorial submission portal, hosted at': '投稿は、次の場所でホストされているジャーナルの編集投稿ポータルを通じてジャーナル レベルで処理されます。',
        'Go to the journal\'s home page via the': 'からジャーナルのホームページにアクセスします。',
        'Reviewers are expected to provide objective, evidence-based assessments in accordance with the': '査読者は、次の規定に従って客観的で証拠に基づいた評価を提供することが期待されています',
        'Repository deposit of accepted manuscripts or published versions is governed by the': '受理された原稿または出版されたバージョンのリポジトリへの寄託は、',
        '. Authors depositing work should cite the version of record accurately and include the published DOI.': '。作品を寄託する著者は、記録のバージョンを正確に引用し、公開された DOI を含める必要があります。',
        'Submission workflow from manuscript preparation to editorial decision.': '原稿準備から編集決定までの投稿ワークフロー。',
        'Discovery, preservation, and persistent identifier information for all journals.': 'すべてのジャーナルの検出、保存、および永続的な識別子情報。',
