        'Portfolio Architecture': 'Портфолио Архитектура',
        'Titles are grouped into four subject clusters for discovery and editorial routing: Technology & Engineering, Health & Sustainability, Policy, Education & Society, and Humanities & Arts.': 'Названия сгруппированы в четыре тематических кластера для поиска и редакционной маршрутизации: «Технологии и инженерия», «Здоровье и устойчивое развитие», «Политика», «Образование и общество», «Гуманитарные науки и искусство».',
