        'Public Access Layer': 'Уровень публичного доступа',
        'Journal pages, policy pages, and published articles are publicly available. DOIs are registered with Crossref for persistent citation and discovery.': 'Страницы журналов, страницы политики и опубликованные статьи являются общедоступными. DOI регистрируются в Crossref для постоянного цитирования и открытия.',
