        '. Authors depositing work should cite the version of record accurately and include the published DOI.': '. Авторы, депонирующие работу, должны точно указать версию записи и включить опубликованный DOI.',
        'Submission workflow from manuscript preparation to editorial decision.': 'Рабочий процесс подачи заявки от подготовки рукописи до принятия редакционного решения.',
        'Discovery, preservation, and persistent identifier information for all journals.': 'Информация об обнаружении, сохранении и постоянном идентификаторе для всех журналов.',
        'Journals in the Panorama Scholarly Group portfolio are indexed in major scholarly discovery databases, preserved in distributed archiving networks, and registered with international identifier systems.': 'Журналы из портфолио Panorama Scholarly Group индексируются в основных базах данных научных открытий, хранятся в распределенных архивных сетях и регистрируются в международных системах идентификации.',
        'Crossref — prefix 10.63802': 'Crossref — префикс 10.63802',
        '. Individual journal DOIs follow the format 10.63802/[journal-id].[volume].[issue].[article-id].': '. Отдельные журналы DOI имеют формат 10.63802/[journal-id].[volume].[issue].[article-id].',
        'Authors depositing preprints or accepted manuscripts in Zenodo or institutional repositories should follow the version and citation guidance in the': 'Авторы, размещающие препринты или принятые рукописи в Zenodo или институциональных репозиториях, должны следовать рекомендациям по версии и цитированию, приведенным в',
        'Filter journals and move directly to the right submission route.': 'Фильтруйте журналы и переходите непосредственно к правильному маршруту отправки.',
        'Use keyword, subject cluster, and ISSN status to identify an appropriate journal, then continue to its journal home page or submission portal.': 'Используйте ключевое слово, тематический кластер и статус ISSN, чтобы определить подходящий журнал, а затем перейдите на домашнюю страницу журнала или на портал подачи.',
        'Access, licensing, and author-rights framework for journal publication.': 'Система доступа, лицензирования и авторских прав для журнальных публикаций.',
