        'Confirm the subject cluster: Technology & Engineering, Health & Sustainability, Policy, Education & Society, or Humanities & Arts.': 'Confirma el grupo temático: Tecnología e ingeniería, Salud y sostenibilidad, Política, educación y sociedad, o Humanidades y artes.',
        'Note article types accepted: original research, review articles, theoretical contributions, creative or reflective work (where applicable).': 'Ten en cuenta los tipos de artículos aceptados: investigación original, artículos de revisión, contribuciones teóricas, trabajo creativo o reflexivo (cuando corresponda).',
        'Using the journal directory': 'Uso del directorio de revistas',
