        'Before uploading your manuscript, confirm that you have reviewed and can comply with the platform\'s shared policy requirements. Individual journals may apply additional requirements — these are detailed on each journal\'s home page.': 'Antes de subir tu manuscrito, confirma que has revisado y puedes cumplir los requisitos de política compartidos de la plataforma. Las revistas individuales pueden aplicar requisitos adicionales, detallados en la página principal de cada revista.',
        'Publication ethics requirements': 'Requisitos de ética de publicación',
