        'publication ethics policy': 'Publikationsethikrichtlinie',
        'with a clear description of the matter.': 'mit einer klaren Beschreibung des Sachverhalts.',
        'and include the relevant journal name and DOI where applicable.': 'und geben Sie gegebenenfalls den relevanten Zeitschriftennamen und DOI an.',
        'allows you to filter by subject cluster and keyword. Each journal entry links directly to the journal home page and submission portal. ISSN status is indicated for journals where registration is complete.': 'ermöglicht die Filterung nach Fachbereich und Stichwort. Jeder Zeitschrifteneintrag verlinkt direkt zur Startseite und zum Einreichungsportal. Der ISSN-Status wird für Zeitschriften angezeigt, bei denen die Registrierung abgeschlossen ist.',
